# Testo e scaletta visiva del video lungo (un'unica fonte per script.py e scenes.py)
# Caso 027: Alceo Dossena, lo scultore dei falsi (Cremona 1878 - Roma 1937)
SC = [
 (0, "Boston, metà degli anni Venti. Un grande museo americano compra una tomba di marmo del Rinascimento. La paga più di centomila dollari. Sulla tomba c'è una data: 1430.", [('Boston', 'i:museum|BOSTON · ANNI VENTI'), ('tomba', 'i:sarcoph|UN MONUMENTO FUNEBRE'), ('centomila', 'big:100.135 $|il prezzo pagato · scheda del museo'), ('1430', 'cal:LA DATA SULLA TOMBA|1430')]),
 (0, 'Il problema è che lo scultore a cui viene attribuita, Mino da Fiesole, nel 1430 aveva un anno. E che quella tomba, in realtà, era stata scolpita a Roma intorno al 1920.', [('problema', 'h:Mino da Fiesole\nnato nel *1429*'), ('anno', "big:1 anno|l'età dello scultore nel 1430"), ('realtà', 'i:workshop|ROMA · INTORNO AL 1920'), ('1920', 'stamp:FALSO')]),
 (0, "L'autore si chiama Alceo Dossena. È uno scalpellino di Cremona. Per anni le sue statue entrano nei musei d'America come capolavori antichi. E a guadagnarci, secondo tutte le ricostruzioni, non è lui.", [("L'autore", 'fig:painter|ALCEO DOSSENA'), ('Cremona', 'map:Cremona|50|Cremona'), ('musei', 'map:Roma|10|Roma,Boston,New York,Cleveland|Roma>Boston'), ('guadagnarci', 'i:moneybag|CHI GUADAGNA?')]),
 (0, 'In questo fascicolo vedremo come nasce la bottega dei falsi, chi li vendeva, quali musei ci sono cascati, come è stato scoperto tutto e perché, alla fine, il falsario è stato assolto.', [('In', 'cover'), ('bottega', 'iii:workshop|LA BOTTEGA|museum|I MUSEI|court|IL PROCESSO'), ('assolto', 't:IL CASO DOSSENA · 1916-1937')]),
 (1, "Per capire questa storia bisogna partire dal mercato. Tra la fine dell'Ottocento e i primi decenni del Novecento, l'arte antica italiana è una merce richiestissima, soprattutto dall'America.", [('Per', "i:shop|IL MERCATO DELL'ANTICO"), ("dell'Ottocento", 'tl:1870|NASCE IL MERCATO;1902|PRIMA LEGGE DI TUTELA;1916|DOSSENA E FASOLI;1928|LO SCANDALO'), ("dall'America", 'map:Roma|10|Firenze,New York|Firenze>New York')]),
 (1, "Il mercato tra Italia e Stati Uniti comincia a crescere negli anni Settanta dell'Ottocento. Il suo centro è Firenze. Lì antiquari, restauratori ed esperti fanno da ponte tra chiese e palazzi da una parte, e collezionisti ricchissimi dall'altra.", [('mercato', 'cal:IL MERCATO|ANNI 1870'), ('Firenze', 'map:Firenze|60|Firenze'), ('antiquari', 'iii:shop|ANTIQUARI|magnifier|ESPERTI|chisel|RESTAURATORI'), ('collezionisti', 'fig:suit|IL COLLEZIONISTA')]),
 (1, "Negli Stati Uniti sono gli anni delle grandi fortune industriali. Acciaio, ferrovie, petrolio. E chi ha fatto fortuna vuole riempire case e musei con l'arte del passato europeo, in particolare con il Rinascimento italiano.", [('Stati', 'i:factory|LE GRANDI FORTUNE'), ('Acciaio', 'iii:factory|ACCIAIO|train|FERROVIE|tanker|PETROLIO'), ('musei', 'i:museum|I NUOVI MUSEI AMERICANI'), ('Rinascimento', 'i:madonna|IL RINASCIMENTO ITALIANO')]),
 (1, "In Italia intanto lo Stato prova a frenare l'uscita delle opere. Nel 1902 arriva la prima legge nazionale sulla tutela del patrimonio artistico. Ma il commercio continua, e la domanda resta altissima.", [('Stato', 'i:ministry|LO STATO'), ('1902', 'doc:LEGGE DI TUTELA · 1902|prima legge nazionale|sul patrimonio artistico'), ('commercio', 'flow:OPERE ANTICHE>COLLEZIONI USA')]),
 (1, 'E qui nasce il problema. Le opere autentiche disponibili sono poche, e ogni anno di meno. La domanda invece cresce. Quando chi compra vuole più di quello che esiste, qualcuno trova il modo di produrlo.', [('problema', 'ii:emptyframe|OPERE AUTENTICHE: POCHE|crowd_icon|DOMANDA: ALTISSIMA'), ('poche', 'i:emptyframe|SEMPRE MENO OPERE'), ('qualcuno', 'stamp:IL VUOTO DA RIEMPIRE')]),
 (1, "Prima di andare avanti, una distinzione importante. Fare una copia, o una scultura nuova nello stile di un'epoca passata, non è un inganno. Diventa un falso quando qualcuno la presenta e la vende come un'opera antica e autentica. Tenetela a mente, perché è il cuore di tutto questo caso.", [('distinzione', 'h:Copia o *falso*?'), ('copia', 'i:signature|COPIA DICHIARATA'), ('vende', 'i:price|VENDUTA COME ANTICA'), ('cuore', 'stamp:IL CUORE DEL CASO')]),
 (1, "I falsari non sono una novità. Nell'Ottocento a Firenze lavora Giovanni Bastianini, i cui busti rinascimentali finiscono anche in grandi musei. A Siena Icilio Federico Joni dipinge tavole che sembrano del Trecento.", [('falsari', 'i:mask|I FALSARI'), ('Bastianini', 'card:GIOVANNI BASTIANINI|Firenze · Ottocento|busti in stile rinascimentale'), ('Joni', 'card:ICILIO FEDERICO JONI|Siena 1866-1946|tavole in stile antico')]),
 (1, 'Joni racconterà la sua vita in un libro di memorie, pubblicato in Italia nel 1932, in cui si definisce un pittore di quadri antichi. Ma il caso più clamoroso di quegli anni riguarda la scultura. E porta a Cremona.', [('Joni', 'i:oldbook|MEMORIE · 1932'), ('pittore', 'h:«Pittore di\n*quadri antichi*»'), ('scultura', 'i:statue|LA SCULTURA'), ('Cremona', 'map:Cremona|60|Cremona')]),
 (2, "Prima di entrare nella bottega, conosciamo i protagonisti. Al centro c'è lui: Alceo Dossena, nato a Cremona nel 1878. Uno scultore che si è formato lavorando la pietra, non nelle accademie.", [('Prima', 'board:0'), ('1878', 'cal:CREMONA|1878'), ('pietra', 'i:marble|IL MARMO')]),
 (2, "Poi ci sono due commercianti d'arte romani: Fasoli e Pallesi. Il nome di battesimo di Fasoli cambia a seconda delle fonti, Alfredo o Alberto. Sono loro che vendono le sculture come antiche.", [('Poi', 'board:1'), ('Pallesi', 'board:2'), ('nome', 'stamp:ALFREDO O ALBERTO?'), ('vendono', 'i:price|«ANTICO»')]),
 (2, "Poi c'è Elia Volpi, grande antiquario di Firenze, nato a Città di Castello nel 1858. È uno dei mercanti più importanti del tempo, legato al Palazzo Davanzati. Molte opere passano da lui prima di attraversare l'oceano.", [('Elia', 'board:3'), ('1858', 'card:ELIA VOLPI|Città di Castello 1858 - Firenze 1938|antiquario'), ("l'oceano", "i:ship|VERSO L'AMERICA")]),
 (2, "Dall'altra parte dell'oceano ci sono i compratori. Musei come quelli di Boston, Cleveland e New York, e collezionisti privati come [Helen Clay Frick,|Èlen Clei Frik,] figlia dell'industriale [Henry Clay Frick.|Ènri Clei Frik.]", [("Dall'altra", 'board:4'), ('Boston', 'iii:museum|BOSTON|museum|CLEVELAND|museum|NEW YORK'), ('Helen', 'fig:suit|LA COLLEZIONISTA')]),
 (2, "E infine c'è chi scoprirà tutto: [Harold Woodbury Parsons,|Hàrold Vùdberi Pàrsons,] storico dell'arte americano che lavora come consulente per i musei degli Stati Uniti, in particolare per quello di [Cleveland.|Clìvland.]", [('infine', 'board:5'), ('Harold', "fig:expert|L'ESPERTO"), ('consulente', 'i:magnifier|CONSULENTE DEI MUSEI')]),
 (3, "Torniamo a Cremona, alla fine dell'Ottocento. È la città dei violini e del Torrazzo, ma è anche una città di cattedrali e chiese piene di sculture medievali e rinascimentali.", [('Torniamo', 'map:Cremona|60|Cremona,Milano'), ('violini', 'i:music|LA CITTÀ DEI VIOLINI'), ('cattedrali', 'i:convent|CHIESE E CATTEDRALI')]),
 (3, "Il giovane Dossena entra alla scuola d'arte cittadina, l'istituto Ala Ponzone. Ma ci resta poco: viene espulso. Su questo le fonti sono d'accordo.", [('giovane', 'fig:man|IL GIOVANE ALCEO'), ('Ala', "i:library|SCUOLA D'ARTE ALA PONZONE"), ('espulso', 'stamp:ESPULSO')]),
 (3, "Sul motivo, invece, c'è un aneddoto che sembra fatto apposta. Secondo il racconto, avrebbe scolpito una piccola Venere, l'avrebbe sotterrata e fatta trovare come se fosse antica. Ma alcuni studiosi lo considerano troppo perfetto per essere vero.", [('motivo', 'i:question|PERCHÉ?'), ('Venere', 'i:statue|UNA PICCOLA VENERE'), ('sotterrata', 'i:spade|SOTTOTERRA'), ('studiosi', 'stamp:FORSE UNA LEGGENDA')]),
 (3, 'Quello che è certo è che il ragazzo comincia a lavorare presto, in una bottega di marmista. Taglia la pietra, fa lapidi, decorazioni, restauri. È lì che impara il mestiere con le mani, giorno dopo giorno.', [('certo', 'i:workshop|LA BOTTEGA DEL MARMISTA'), ('pietra', 'i:chisel|IL MESTIERE'), ('restauri', 'iii:marble|LAPIDI|chisel|DECORAZIONI|magnifier|RESTAURI')]),
 (3, "Lavora come restauratore anche a Milano. E restaurare un'opera antica significa studiarla da vicino: come è fatta, come è invecchiata, dove si è rotta. Una scuola perfetta per chi un giorno vorrà imitarla.", [('Milano', 'map:Milano|60|Cremona,Milano'), ('restaurare', 'i:curator|STUDIARE DA VICINO'), ('imitarla', "h:La scuola\ndell'*imitazione*")]),
 (3, 'Più tardi Dossena si presenterà come un autodidatta, uno che ha imparato guardando le sculture delle chiese di Cremona. Un racconto in parte vero, in parte costruito: la scuola e le botteghe, in realtà, le aveva frequentate.', [('autodidatta', 'fig:painter|DOSSENA'), ('autodidatta', 'i:eye|IMPARA GUARDANDO'), ('costruito', 'stamp:IN PARTE VERO')]),
 (3, "Facciamo un conto. Quando scoppia lo scandalo, nel 1928, Dossena ha cinquant'anni. Quando vende la sua prima statua a Fasoli, intorno al 1916, ne ha circa trentotto. Non è un ragazzo di bottega: è un artigiano maturo, con vent'anni di mestiere alle spalle.", [('conto', 'tl:1878|NASCE;1916|≈ 38 ANNI;1928|50 ANNI'), ('trentotto', 'big:≈ 38 anni|al primo pezzo venduto'), ('artigiano', "i:chisel|VENT'ANNI DI MESTIERE")]),
 (3, "Poi arriva la Prima guerra mondiale. Anche Dossena fa il servizio militare. Ed è in quegli anni, secondo tutte le ricostruzioni, che la sua vita prende un'altra strada.", [('Prima', 'cal:LA GRANDE GUERRA|1915-1918'), ('militare', 'fig:guard|IL SERVIZIO MILITARE'), ('strada', 'flow:SCALPELLINO>SCULTORE DI FALSI')]),
 (4, 'Il racconto più diffuso è questo. Siamo intorno al 1916. Dossena, in licenza e senza soldi, ha con sé una piccola Madonna col Bambino, fatta da lui e invecchiata.', [('racconto', 'cal:IL PRIMO PEZZO|1916'), ('soldi', 'i:payenv|SENZA SOLDI'), ('Madonna', 'i:tondo|UNA PICCOLA MADONNA')]),
 (4, "Lo vende per cento lire a Fasoli, che lo compra credendolo antico. Più tardi Fasoli si accorge che non lo è. E invece di arrabbiarsi, cerca chi l'ha fatto.", [('cento', 'big:100 lire|il prezzo del primo pezzo'), ('antico', 'i:magnifier|«È ANTICO»'), ('accorge', 'stamp:NON È ANTICO'), ('cerca', 'fig:suit|IL MERCANTE')]),
 (4, "Attenzione però: alcuni studiosi ritengono che questo incontro, così come viene raccontato, non sia verificabile. I dettagli cambiano da una versione all'altra. Quello che le fonti confermano è che Dossena e Fasoli si incontrano negli anni della guerra, e che da lì nasce una collaborazione.", [('Attenzione', 'i:question|UN RACCONTO VERIFICABILE?'), ('dettagli', 'stamp:VERSIONI DIVERSE'), ('incontro', "i:handshake|L'INCONTRO"), ('collaborazione', 'board:2')]),
 (4, 'A Roma, tra gli anni della guerra e quelli subito dopo, Fasoli e Pallesi organizzano il lavoro. Danno a Dossena uno stipendio mensile, materiali e spazi. Lui scolpisce, loro vendono.', [('Roma', 'map:Roma|60|Roma'), ('stipendio', 'i:payenv|LO STIPENDIO MENSILE'), ('scolpisce', 'lab:1'), ('vendono', 'flow:DOSSENA SCOLPISCE>I MERCANTI VENDONO')]),
 (4, 'I mercanti commissionano le opere: suggeriscono soggetti, stili, modelli. Madonne col Bambino, molto richieste sul mercato americano. Angeli, santi, sepolcri. Ma anche figure greche ed etrusche.', [('commissionano', 'doc:COMMISSIONE|soggetto: Madonna col Bambino|stile: Trecento senese|materiale: marmo'), ('Madonne', 'lab:2'), ('greche', 'lab:3')]),
 (4, 'La bottega di Dossena è la nostra scenografia. Ogni volta che una statua esce da qui, ne cambia il nome. Qui è di Dossena. Fuori, diventa di qualcun altro.', [('bottega', 'lab:3'), ('nome', 'flow:DOSSENA>«MAESTRO ANTICO»'), ('Fuori', 'stamp:CAMBIO DI NOME')]),
 (4, 'Gli stili sono quelli dei grandi: Giovanni e Nino Pisano, Simone Martini, Donatello, Mino da Fiesole, Verrocchio, il Vecchietta. Nomi da cui un museo, allora come oggi, non riesce a staccare gli occhi.', [('stili', 'card:GLI STILI IMITATI|Giovanni e Nino Pisano · Simone Martini|Donatello · Mino da Fiesole|Verrocchio · Vecchietta'), ('museo', 'i:museum|I NOMI CHE FANNO IL PREZZO')]),
 (4, "Ma c'è un dettaglio importante. Dossena di solito non copia un'opera esistente. Inventa un'opera nuova nello stile di un maestro, a volte mescolando dettagli di artisti diversi. Per questo il confronto con un originale non basta a smascherarla.", [('dettaglio', 'h:Non *copia*'), ('Inventa', 'i:workshop|INVENTA NELLO STILE'), ('confronto', "ii:statue|L'ORIGINALE?|question|NON ESISTE")]),
 (4, 'Lui stesso, anni dopo, dirà una frase che riassume tutto: ho inventato alla maniera dei grandi maestri, ma ho sempre inventato. Secondo lui, non ha mai fatto altro che opere originali.', [('stesso', 'h:«Ho sempre\n*inventato*»'), ('originali', 'stamp:OPERE «ORIGINALI»')]),
 (4, "Poi c'è l'invecchiamento. Le fonti raccontano di marmi trattati per sembrare consumati dai secoli, di rotture e mancanze studiate, come se il tempo le avesse rovinate. Non entriamo nei dettagli: basta sapere che il risultato ingannava anche gli esperti.", [("l'invecchiamento", "i:hourglass|L'INVECCHIAMENTO"), ('rotture', 'i:broken|ROTTURE STUDIATE'), ('esperti', 'i:curator|ESPERTI INGANNATI')]),
 (4, "Resta un problema. Se all'improvviso compaiono decine di sculture antiche mai viste, da dove arrivano? Serve una storia. E i mercanti ne mettono in giro una molto bella.", [('problema', 'i:question|DA DOVE ARRIVANO?'), ('decine', 'lab:4'), ('storia', 'stamp:SERVE UNA STORIA')]),
 (4, "Un'antica abbazia in Toscana, distrutta da un terremoto, dalle cui rovine sarebbero riemerse queste opere. Un'abbazia che non è mai esistita. Le versioni sul luogo cambiano, ma il trucco è sempre lo stesso: una provenienza romantica e impossibile da controllare.", [("Un'antica", "i:abbey_x|L'ABBAZIA"), ('terremoto', 'i:quake|IL TERREMOTO'), ('esistita', 'stamp:MAI ESISTITA'), ('provenienza', 'h:Una provenienza\n*impossibile da controllare*')]),
 (4, "E Dossena quanto guadagna? Poco, secondo tutte le fonti. Lo stipendio è descritto come magro, e c'è chi dice che non bastava nemmeno a coprire spese e materiali. Le cifre precise, invece, non coincidono.", [('Dossena', 'i:payenv|LO STIPENDIO'), ('magro', 'ii:payenv|A DOSSENA: POCO|moneybag|AI MERCANTI: QUASI TUTTO'), ('cifre', 'stamp:CIFRE NON CONCORDI')]),
 (4, 'Facciamo un primo riepilogo. Uno scalpellino di talento, due mercanti che vendono, un antiquario che fa da ponte, un mercato affamato. E una storia di copertura. Ora vediamo dove finiscono le statue.', [('riepilogo', 'board:3'), ('mercato', 'tl:1878|NASCE DOSSENA;1916|IL PRIMO PEZZO;ANNI 20|LA BOTTEGA;1928|?'), ('statue', 'map:Roma|10|Roma,Boston,New York,Cleveland|Roma>Boston')]),
 (5, 'Prima tappa: Boston. Il [Museum of Fine Arts|Miusìam of fain arts] è uno dei grandi musei americani. E nel 1923 e 1924 compra quella che viene presentata come una tomba di Mino da Fiesole.', [('Prima', 'map:Boston|50|Boston'), ('Museum', 'mus:1'), ('tomba', 'i:sarcoph|«MINO DA FIESOLE»')]),
 (5, 'Il [Museum of Fine Arts|Miusìam of fain arts] di Boston era nato nel 1870. Negli anni Venti è già uno dei musei più importanti degli Stati Uniti, con collezioni che arrivano da tutto il mondo. Comprare un grande monumento del Rinascimento italiano è, per un museo così, un colpo di prestigio.', [('Museum', 'cal:BOSTON · IL MUSEO|1870'), ('Venti', 'i:museum|UNO DEI GRANDI MUSEI USA'), ('prestigio', 'stamp:UN COLPO DI PRESTIGIO')]),
 (5, 'Chi era Mino da Fiesole? Uno scultore fiorentino del Quattrocento, nato nel 1429 e morto nel 1484, famoso proprio per i monumenti funebri e i ritratti in marmo. Una firma che vale moltissimo.', [('Chi', 'card:MINO DA FIESOLE|scultore · 1429-1484|monumenti funebri e ritratti in marmo'), ('firma', 'i:signature|UNA FIRMA CHE VALE')]),
 (5, 'La tomba è dedicata a una donna della nobiltà romana. Il nome viene scritto in modi diversi: Maria Caterina Savelli secondo alcune fonti, Maria Catharina Sabello sulla scheda del museo.', [('tomba', 'i:sarcoph|IL MONUMENTO FUNEBRE'), ('Savelli', 'ii:sarcoph|SAVELLI|sarcoph|SABELLO'), ('scheda', 'stamp:NOMI NON CONCORDI')]),
 (5, 'Il percorso è ricostruito dalla scheda del museo. Entro il 1922 la tomba viene venduta come opera di Mino, probabilmente dai mercanti di Dossena, a Elia Volpi, a Firenze. Nel 1923 Volpi la rivende, tramite il mercante veneziano Carlo Balboni.', [('percorso', 'map:Firenze|40|Roma,Firenze,Venezia|Roma>Firenze>Venezia'), ('1922', 'tl:1920|ROMA · LA BOTTEGA;1922|FIRENZE · VOLPI;1923|VENEZIA · BALBONI;1924|BOSTON'), ('Balboni', 'fig:suit|IL MERCANTE VENEZIANO')]),
 (5, "Il prezzo: [100.135 dollari.|centomila centotrentacinque dollari.] Con l'indice dei prezzi americano, oggi sarebbero quasi due milioni di dollari. La tomba entra nelle collezioni del museo nell'aprile del 1924.", [('prezzo', 'big:100.135 $|il prezzo · 1923'), ("l'indice", 'big:≈ 1,9 MLN $|di oggi · stima con indice CPI USA'), ("nell'aprile", 'cal:BOSTON|APR 1924')]),
 (5, 'E la data 1430? È proprio quella a non tornare. Se Mino è nato nel 1429, nel 1430 aveva un anno. Un bambino di un anno a cui viene attribuito un monumento in marmo. Eppure, per anni, nessuno se ne preoccupa.', [('1430', 'tl:1429|NASCE MINO;1430|LA DATA SULLA TOMBA'), ('anno', "big:1 ANNO|l'età di Mino nel 1430"), ('preoccupa', 'stamp:NESSUNO SE NE ACCORGE')]),
 (5, 'Il museo di [Cleveland|Clìvland] è giovane: apre nel 1916. Negli anni Venti sta costruendo le sue collezioni e ha bisogno di pezzi importanti. Per questo si affida a consulenti in Europa, come [Harold Parsons,|Hàrold Pàrsons,] che segue il mercato italiano.', [('museo', 'cal:CLEVELAND · IL MUSEO|1916'), ('Venti', 'i:crate|COLLEZIONI DA COSTRUIRE'), ('Harold', 'fig:expert|IL CONSULENTE')]),
 (5, "Seconda tappa: Cleveland, in Ohio. Anche qui il museo si fida. E compra, tra le altre cose, una statua presentata come un'Atena greca antica. Un pezzo da museo, con le sue erosioni secolari.", [('Seconda', 'map:Cleveland|40|Cleveland,Boston'), ('museo', 'mus:2'), ("un'Atena", 'i:athena|«ATENA GRECA»'), ('erosioni', 'i:broken|EROSIONI «SECOLARI»')]),
 (5, 'Una kore è un tipo di statua greca arcaica: una giovane donna in piedi, vestita, con un leggero sorriso. Gli originali risalgono soprattutto al sesto secolo avanti Cristo. Sono rarissimi sul mercato, ed è proprio questo a renderli così preziosi.', [('kore', 'i:kore|LA KORE'), ('sesto', 'cal:GRECIA ARCAICA|VI SEC. a.C.'), ('rarissimi', 'stamp:RARISSIMI')]),
 (5, 'Terza tappa: New York. Al Metropolitan Museum of Art arriva una fanciulla greca in stile arcaico, una kore, con il suo panneggio e il suo sorriso enigmatico. Anche lei, come si scoprirà, viene dalla stessa bottega romana.', [('Terza', 'map:New York|40|New York,Boston,Cleveland'), ('Metropolitan', 'mus:3'), ('kore', 'i:kore|«KORE GRECA»'), ('bottega', 'lab:4')]),
 (5, "E poi c'è il pezzo più costoso. Nel 1924 [Helen Clay Frick|Èlen Clei Frik] compra da Elia Volpi una coppia di statue in marmo: un angelo e una Vergine, un'Annunciazione. Sono attribuite a Simone Martini.", [('costoso', 'fig:suit|HELEN CLAY FRICK'), ('1924', "cal:L'ACQUISTO|1924"), ('angelo', "i:annunc|L'ANNUNCIAZIONE"), ('Simone', 'stamp:«SIMONE MARTINI»')]),
 (5, 'Le statue portano iscritte le iniziali del nome di Simone. Il dettaglio curioso è che Simone Martini, il grande maestro senese del Trecento, è famoso come pittore. La sua Annunciazione più celebre è un dipinto, agli Uffizi.', [('iniziali', 'i:signature|LE INIZIALI'), ('pittore', 'i:easel|UN PITTORE'), ('Uffizi', 'map:Firenze|60|Firenze')]),
 (5, "Chi era [Helen Clay Frick?|Èlen Clei Frik?] La figlia di un magnate dell'acciaio e del carbone di [Pittsburgh,|Pìtsburg,] [Henry Clay Frick,|Ènri Clei Frik,] grande collezionista d'arte. Dopo la morte del padre, nel 1919, Helen diventa a sua volta una collezionista e una figura importante del mondo dei musei.", [('Helen', 'fig:suit|HELEN CLAY FRICK'), ("dell'acciaio", 'i:factory|ACCIAIO E CARBONE'), ('1919', 'cal:MORTE DEL PADRE|1919'), ('musei', 'i:museum|IL MONDO DEI MUSEI')]),
 (5, "Simone Martini è uno dei grandi pittori del Trecento. Nasce a Siena intorno al 1284 e muore ad Avignone nel 1344, dove lavorava per la corte dei papi. Di lui si conoscono dipinti, affreschi, tavole d'oro. Sculture in marmo, no.", [('Simone', 'card:SIMONE MARTINI|Siena ≈ 1284 - Avignone 1344|pittore'), ('Avignone', 'map:Siena|20|Siena'), ('dipinti', 'i:easel|DIPINTI E AFFRESCHI'), ('no', 'stamp:SCULTURE? NO')]),
 (5, "Quanto le paga? Secondo più fonti centocinquantamila dollari. Secondo un'altra ricostruzione addirittura duecentoventicinquemila. Anche prendendo la cifra più bassa, con l'indice dei prezzi americano oggi sarebbero quasi tre milioni di dollari.", [('Quanto', 'bars:150.000 $|150|225.000 $|225'), ('cifra', 'big:≈ 2,8 MLN $|di oggi · 150.000 $ del 1924 · indice CPI USA'), ('dollari', 'stamp:PREZZI NON CONCORDI')]),
 (5, "Ecco il quadro di metà anni Venti. Una tomba a Boston, un'Atena a Cleveland, una kore a New York, un'Annunciazione nella collezione Frick. E molte altre sculture vendute a collezionisti e musei in tutto il mondo.", [('Ecco', 'mus:4'), ('molte', 'map:Roma|10|Roma,Boston,Cleveland|Roma>Boston'), ('mondo', 't:METÀ ANNI VENTI · LE STATUE IN AMERICA')]),
 (5, 'Se questa storia ti sta piacendo, iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.', [('Se', 'subscribe')]),
 (6, 'Ma un mercato così non può durare per sempre. Più opere escono dalla bottega, più aumentano le probabilità che qualcuno noti qualcosa. E intorno al 1926 cominciano a girare i primi sospetti.', [('mercato', 'lab:4'), ('probabilità', 'i:eye|PIÙ OPERE, PIÙ OCCHI'), ('1926', 'cal:I PRIMI SOSPETTI|1926')]),
 (6, 'Le voci parlano di un artista italiano capace di fare sculture greche, etrusche, gotiche e rinascimentali. Troppi capolavori stanno comparendo dal nulla, in pochi anni.', [('voci', 'i:ear|LE VOCI'), ('greche', 'iii:kore|GRECHE|statue|GOTICHE|madonna|RINASCIMENTALI'), ('nulla', 'stamp:TROPPI CAPOLAVORI')]),
 (6, 'Alcuni compratori cominciano a chiedere la restituzione dei soldi. Le fonti non dicono quanti, né quando esattamente. Ma il clima cambia: chi aveva comprato con entusiasmo comincia a guardare le proprie statue con altri occhi.', [('compratori', 'i:money|LA RESTITUZIONE'), ('fonti', 'stamp:QUANTI? NON SI SA'), ('occhi', 'i:curator|CON ALTRI OCCHI')]),
 (6, "Qui entra in gioco una domanda che i musei si fanno ancora oggi: come si capisce se un'opera è autentica? Con lo stile, con i documenti, con la storia dei passaggi di proprietà, con le analisi.", [('domanda', 'i:question|È AUTENTICA?'), ('stile', 'iii:eye|LO STILE|letter|I DOCUMENTI|xray|LE ANALISI')]),
 (6, "Nel caso Dossena, lo stile ha ingannato quasi tutti, perché non c'era un originale da confrontare. I documenti mancavano o raccontavano di abbazie inesistenti. E le analisi scientifiche, negli anni Venti, erano ancora agli inizi.", [('stile', 'ii:statue|LO STILE|question|ORIGINALE?'), ('documenti', 'i:abbey_x|DOCUMENTI? ABBAZIE INESISTENTI'), ('analisi', 'i:xray|LE ANALISI · AGLI INIZI')]),
 (6, "Rimane un'ultima strada: trovare chi le ha fatte. E qui comincia la parte investigativa della storia, quella che porta da New York e Cleveland fino a una bottega di Roma.", [('strada', "fig:expert|L'INDAGINE"), ('Cleveland', 'map:Roma|10|Cleveland,New York,Roma|Cleveland>Roma'), ('bottega', 'lab:4')]),
 (7, "La svolta arriva nel 1928. Il protagonista è [Harold Woodbury Parsons,|Hàrold Vùdberi Pàrsons,] lo storico dell'arte che lavora per il museo di [Cleveland.|Clìvland.] Parte dall'America e viene in Italia a cercare l'autore.", [('svolta', 'cal:LA SVOLTA|1928'), ('Harold', 'fig:expert|HAROLD W. PARSONS'), ('Italia', 'map:Roma|10|Cleveland,Roma|Cleveland>Roma')]),
 (7, 'Lo trova. Ed è qui che la storia prende una piega inattesa. Dossena non si nasconde. Apre il suo studio romano a [Parsons|Pàrsons] e gli mostra le fotografie della sua produzione.', [('trova', 'board:5'), ('studio', 'lab:4'), ('fotografie', 'i:photos|LE FOTOGRAFIE')]),
 (7, "Su quelle fotografie ci sono opere che [Parsons|Pàrsons] conosce bene, perché le ha viste nei musei americani. E Dossena ammette di esserne l'autore, insieme ad altre acquistate da musei degli Stati Uniti.", [('fotografie', 'i:curator|IL CONFRONTO'), ('musei', 'mus:4'), ('ammette', 'h:«Le ho fatte\n*io*»')]),
 (7, 'Perché lo fa? La sua versione è semplice: lui faceva sculture nello stile antico su richiesta degli intermediari. Non sapeva, dice, che sarebbero state vendute come autentiche. Pensava che finissero a collezionisti di arte in stile antico.', [('Perché', 'i:question|PERCHÉ PARLA?'), ('richiesta', 'flow:COMMISSIONE>SCULTURA «IN STILE»'), ('sapeva', 'stamp:«NON SAPEVO»')]),
 (7, 'Ma nel 1928 Dossena scopre una cosa che non gli piace: le sue opere sono esposte nei musei come antichità originali, e i mercanti si sono tenuti la quasi totalità dei guadagni. Lui, secondo tutte le fonti, è stato pagato poco.', [('1928', 'cal:DOSSENA SCOPRE|1928'), ('esposte', 'mus:4'), ('mercanti', 'ii:payenv|A DOSSENA: POCO|moneybag|AI MERCANTI: QUASI TUTTO'), ('poco', 'stamp:PAGATO POCO')]),
 (7, "Tra novembre e dicembre del 1928 lo scandalo diventa internazionale. Il settimanale americano [TIME|Taim] il 17 dicembre scrive che i custodi di un'Atena a [Cleveland,|Clìvland,] di una tomba a Boston e di una fanciulla greca al [Metropolitan|Metropòlitan] sono stati ingannati, e ora sono imbarazzati.", [('novembre', 'cal:LO SCANDALO|FINE 1928'), ('TIME', "doc:SETTIMANALE USA · 17/12/1928|Cleveland: un'Atena|Boston: una tomba|New York: una fanciulla greca"), ('imbarazzati', 'iii:athena|CLEVELAND|sarcoph|BOSTON|kore|NEW YORK')]),
 (7, "Facciamo il punto a metà del fascicolo. Abbiamo uno scalpellino di Cremona, una bottega a Roma, due mercanti, un antiquario fiorentino, statue in tre grandi musei e in una collezione privata. E ora, un falsario che confessa di essere l'autore.", [('punto', 'board:5'), ('bottega', 'tl:1916|IL PRIMO PEZZO;1922-24|LE VENDITE;1926|I SOSPETTI;1928|LA CONFESSIONE'), ('falsario', "stamp:L'AUTORE PARLA")]),
 (7, "Le reazioni non sono tutte uguali. A Boston l'autenticità della tomba viene messa in dubbio, ma la questione non si chiude subito. Il dibattito, scrive oggi lo stesso museo nella sua scheda, durerà a lungo.", [('reazioni', 'i:meeting|LE REAZIONI'), ("l'autenticità", 'i:sarcoph|AUTENTICITÀ IN DUBBIO'), ('dibattito', 'stamp:UN DIBATTITO LUNGO')]),
 (7, "Anche l'Annunciazione della collezione Frick, attribuita a Simone Martini, risulta opera di Dossena. Elia Volpi, che l'aveva venduta, esce dallo scandalo screditato e, secondo le ricostruzioni, quasi sul lastrico.", [("l'Annunciazione", "i:annunc|L'ANNUNCIAZIONE"), ('Dossena', 'stamp:OPERA DI DOSSENA'), ('Volpi', 'board:3'), ('lastrico', 'i:money|QUASI SUL LASTRICO')]),
 (8, 'Lo scandalo ora arriva in tribunale, in Italia. E qui la storia diventa ancora più aggrovigliata, perché i processi sono due, in direzioni opposte.', [('scandalo', 'court:IN TRIBUNALE'), ('due', 'ii:gavel|DOSSENA ACCUSATO|gavel|FASOLI ACCUSATO')]),
 (8, "Prima di vedere come finisce, ricordiamo che siamo negli anni del fascismo. Dal 1926 le leggi del regime hanno sciolto i partiti di opposizione e creato un tribunale speciale per i reati politici. In quel clima, una denuncia per frasi contro il capo del governo è un'arma potente.", [('fascismo', 'cal:LE LEGGI DEL REGIME|1926'), ('tribunale', 'court:TRIBUNALE SPECIALE'), ("un'arma", "stamp:UN'ARMA POTENTE")]),
 (8, 'Primo fronte. Dossena porta in tribunale i suoi mercanti. Li accusa, in sostanza, di aver venduto le sue opere come antiche a sua insaputa e di essersi tenuti i guadagni. Due fonti indicano la sua richiesta in sessantaseimila dollari.', [('Primo', 'flow:DOSSENA>I MERCANTI'), ('accusa', 'doc:DENUNCIA|contro: i mercanti|vendite come opere antiche|guadagni trattenuti'), ('sessantaseimila', 'big:66.000 $|la richiesta di Dossena')]),
 (8, "Secondo fronte. Fasoli contrattacca. Denuncia Dossena per antifascismo: sostiene che lo scultore abbia pronunciato frasi offensive contro Mussolini. Siamo nell'Italia del regime, e un'accusa del genere è pesantissima.", [('Secondo', 'flow:FASOLI>DOSSENA'), ('antifascismo', 'stamp:ACCUSA: ANTIFASCISMO'), ('regime', "cal:L'ITALIA DEL REGIME|1928")]),
 (8, 'Le fonti leggono quella denuncia nello stesso modo: una mossa per screditare un testimone scomodo. Se Dossena viene condannato o perde credibilità, la sua versione sulle vendite pesa molto meno.', [('fonti', 'i:magnifier|LA LETTURA DELLE FONTI'), ('testimone', 'fig:painter|IL TESTIMONE SCOMODO'), ('credibilità', 'i:warn|CREDIBILITÀ A RISCHIO')]),
 (8, 'A questo punto entra in scena un nome inaspettato: Roberto Farinacci, gerarca fascista di Cremona, la città natale di Dossena, ed ex segretario del partito. Secondo le ricostruzioni, interviene a favore dello scultore.', [('A', 'card:ROBERTO FARINACCI|gerarca fascista · Cremona|segretario del partito 1925-1926'), ('partito', 'map:Cremona|60|Cremona,Roma'), ('favore', 'stamp:INTERVIENE')]),
 (8, "L'esito, per Dossena, è l'assoluzione per insufficienza di prove. Lo scultore esce dal processo senza condanna. E l'opinione pubblica si schiera con lui: viene visto come la vittima di due trafficanti.", [("L'esito", 'court:ASSOLTO'), ('insufficienza', 'stamp:INSUFFICIENZA DI PROVE'), ('pubblica', 'crowd')]),
 (8, "Cosa significa assolto per insufficienza di prove? Era una formula prevista dal codice di allora: l'imputato non viene condannato, ma senza una dichiarazione piena di innocenza. Il nuovo codice di procedura penale, entrato in vigore nel 1989, l'ha eliminata.", [('significa', 'h:Insufficienza\ndi *prove*'), ('formula', 'doc:SENTENZA|imputato: assolto|formula: insufficienza di prove'), ('1989', 'cal:NUOVO CODICE|1989')]),
 (8, "E la causa di Dossena contro Fasoli? Qui le fonti non coincidono, e conviene dirlo chiaramente. Una ricostruzione dice che Dossena ottenne un risarcimento pari a circa sessantaseimila dollari. Un'altra dice che non ricevette mai un centesimo.", [('causa', 'i:court|LA CAUSA CONTRO FASOLI'), ('risarcimento', 'ii:dollar|66.000 $?|question|NIENTE?'), ('centesimo', 'stamp:VERSIONI NON CONCORDI')]),
 (8, "Un'altra fonte ancora racconta che nel dicembre del 1930 anche Fasoli fu assolto per insufficienza di prove. E un'altra sostiene che la causa venne abbandonata. Quello che nessuna fonte riporta è una condanna dei mercanti.", [('fonte', "i:oldbook|UN'ALTRA FONTE"), ('dicembre', 'cal:FASOLI ASSOLTO?|DIC 1930'), ('abbandonata', 'i:emptyframe|CAUSA ABBANDONATA?'), ('condanna', 'stamp:NESSUNA CONDANNA NOTA')]),
 (8, "Quindi, alla fine, sul piano giudiziario nessuno risulta condannato. Dossena è assolto. I mercanti non risultano condannati. E le statue restano nei magazzini dei musei, con un'etichetta che nessuno sa più come scrivere.", [('Quindi', 'court:NESSUN CONDANNATO'), ('assolto', 'iii:gavel|DOSSENA ASSOLTO|nophoto|MERCANTI NON CONDANNATI|museum|MUSEI IMBARAZZATI'), ("un'etichetta", 'card:ETICHETTA|«Mino da Fiesole»?|«Alceo Dossena»?')]),
 (9, 'Dopo lo scandalo, la vita di Dossena cambia di nuovo. Interrompe i rapporti con gli antiquari. E fa una cosa che prima non faceva: comincia a firmare e datare le sue opere.', [('Dopo', 'cal:DOPO LO SCANDALO|1929'), ('rapporti', 'stamp:FINE DEI RAPPORTI'), ('firmare', 'i:signature|FIRMA E DATA')]),
 (9, 'Per un momento diventa famoso. La stampa lo presenta come un artista di grande talento, vittima di due trafficanti. Lui alterna lavori in stile antico a opere di gusto contemporaneo, riceve commissioni pubbliche e private.', [('famoso', 'i:newspaper|LA FAMA'), ('alterna', 'ii:madonna|STILE ANTICO|statue|GUSTO MODERNO'), ('commissioni', 'i:letter|NUOVE COMMISSIONI')]),
 (9, "Le sue opere vengono esposte in mostre in Italia e all'estero, finalmente con il suo nome. Ma la fama dura poco. Senza la firma di un grande maestro antico, quelle stesse sculture interessano molto meno.", [('mostre', 'map:Roma|20|Roma,Milano'), ('nome', 'i:museum|CON IL SUO NOME'), ('fama', 'i:hourglass|UNA FAMA BREVE')]),
 (9, "Intanto il mondo cambia. Nel 1929 arriva il crollo di Wall Street, e negli anni successivi la crisi colpisce anche il mercato dell'arte. I collezionisti americani comprano meno, i prezzi scendono. Per chi vive di sculture, è il momento peggiore.", [('1929', 'cal:WALL STREET|1929'), ('crisi', 'i:money|PREZZI IN CALO'), ('peggiore', 'stamp:IL MOMENTO PEGGIORE')]),
 (9, "Il paradosso arriva nel 1933. Trentanove opere di Dossena vanno all'asta, vendute come opere sue. Incassano in tutto circa novemila dollari. Una fonte indica la cifra esatta: [9.125 dollari.|novemilacentoventicinque dollari.]", [('paradosso', "cal:L'ASTA|1933"), ('Trentanove', 'i:auction|39 OPERE'), ('novemila', 'big:≈ 9.000 $|in tutto · 39 opere')]),
 (9, 'Facciamo un conto. Novemila dollari divisi per trentanove opere fanno circa duecentotrenta dollari a scultura. La sola tomba di Boston, venduta come Mino da Fiesole, era costata centomila. In pratica, una sola tomba vale undici aste intere.', [('conto', 'big:≈ 230 $|a scultura · 9.125 $ ÷ 39'), ('tomba', 'bars:ASTA 1933 (39 OPERE)|9|TOMBA DI BOSTON|100'), ('undici', 'big:× 11|una tomba = 11 aste intere')]),
 (9, "È la stessa mano, lo stesso marmo, lo stesso talento. Cambia solo il nome scritto sul cartellino. Ed è forse la lezione più amara di tutta la storia: nel mercato dell'arte, il prezzo spesso lo fa la firma, non l'opera.", [('mano', 'ii:sarcoph|«MINO» · 100.135 $|statue|«DOSSENA» · ≈ 230 $'), ('cartellino', 'i:price|IL CARTELLINO'), ('firma', 'h:Il prezzo\nlo fa la *firma*')]),
 (9, "Ancora un conto. Tra la data incisa sulla tomba di Boston, 1430, e l'anno in cui è stata davvero scolpita, intorno al 1920, passano quasi cinquecento anni. È il salto nel tempo che Dossena è riuscito a far credere a un grande museo.", [('conto', 'tl:1430|LA DATA INCISA;1920|LA DATA VERA'), ('cinquecento', 'big:≈ 490 anni|il salto nel tempo'), ('museo', 'i:museum|IL MUSEO INGANNATO')]),
 (9, 'Alceo Dossena muore a Roma nel 1937. Muore povero, quasi dimenticato. Su questo le fonti concordano, anche se una indica come anno di morte il 1939.', [('Alceo', 'cal:ROMA|1937'), ('povero', 'stamp:POVERO E DIMENTICATO'), ('1939', 't:1937 · PER UNA FONTE 1939')]),
 (9, "E le statue? [Helen Clay Frick|Èlen Clei Frik] dona l'Annunciazione all'Università di [Pittsburgh.|Pìtsburg.] Le due figure sono ancora lì, esposte nell'edificio dedicato alle belle arti dell'università.", [('statue', "i:annunc|L'ANNUNCIAZIONE"), ('dona', 'i:handshake|IL DONO'), ('Pittsburgh', 'map:Pittsburgh|40|Pittsburgh,Cleveland,New York')]),
 (9, 'La tomba di Boston è ancora nel catalogo del museo. Oggi la scheda la intitola tomba in stile rinascimentale, con due nomi: Alceo Dossena e Mino da Fiesole. E la data: intorno al 1920.', [('tomba', 'i:sarcoph|BOSTON'), ('scheda', 'card:SCHEDA DEL MUSEO|«tomba in stile rinascimentale»|Alceo Dossena · Mino da Fiesole|intorno al 1920'), ('1920', 'stamp:INTORNO AL 1920')]),
 (9, 'In Italia, una collezione di opere di Dossena, quella della famiglia di un avvocato toscano, Ansaldi, è stata donata allo Stato. Oggi si trova nel museo civico di Pescia, in provincia di Pistoia.', [('Italia', 'map:Pescia|50|Pescia,Firenze'), ('Ansaldi', 'card:COLLEZIONE ANSALDI|donata allo Stato|oggi al museo civico di Pescia'), ('Pescia', 'i:museum|PESCIA')]),
 (9, 'Anche Cremona, la sua città, conserva opere di Dossena nel museo civico Ala Ponzone. Lo stesso nome della scuola da cui era stato espulso da ragazzo.', [('Cremona', 'map:Cremona|60|Cremona'), ('Ala', 'i:tondo|MUSEO ALA PONZONE'), ('espulso', 'stamp:IL CERCHIO SI CHIUDE')]),
 (9, "E nel 2021 il MART di Rovereto gli dedica una grande mostra: il falso nell'arte, Alceo Dossena e la scultura italiana del Rinascimento. Dal 3 ottobre 2021 al 9 gennaio 2022, a cura di Dario Del Bufalo e Marco Horak.", [('2021', 'map:Rovereto|50|Rovereto'), ('falso', "doc:IL FALSO NELL'ARTE|Alceo Dossena e la scultura|italiana del Rinascimento|3/10/2021 - 9/1/2022"), ('cura', 'iii:museum|ROVERETO|statue|DOSSENA|madonna|IL RINASCIMENTO')]),
 (9, "Il titolo di un articolo dedicato a quella mostra riassume bene il cambio di sguardo di questi anni: Dossena, più di un falsario. Oggi le sue opere vengono studiate anche come opere d'arte del Novecento, con il loro vero nome.", [('titolo', 'h:«Più di un\n*falsario*»'), ('Novecento', 'i:statue|ARTE DEL NOVECENTO'), ('nome', 'i:signature|CON IL SUO VERO NOME')]),
 (9, 'Le fonti la descrivono come il nucleo più vasto di opere di Dossena mai mostrato al pubblico. In una sezione, la mostra ricordava anche un altro caso famoso: le false teste di Modigliani ripescate a Livorno nel 1984, di cui abbiamo parlato in un fascicolo precedente.', [('nucleo', 'lab:4'), ('Modigliani', 'cal:LIVORNO|1984'), ('fascicolo', 'stamp:FASCICOLO N. 009')]),
 (9, 'Un altro riepilogo, per chi è appena arrivato. Dossena scolpisce, i mercanti vendono come antiche, i musei comprano, nel 1928 arriva la confessione, il processo lo assolve, le statue restano dove sono, e lui muore povero.', [('riepilogo', 'board:5'), ('Dossena', "tl:1916|IL PRIMO PEZZO;1924|BOSTON E FRICK;1928|LO SCANDALO;1933|L'ASTA;1937|LA MORTE")]),
 (10, 'Restano diverse domande. La prima è anche la più importante: Dossena era davvero una vittima, o sapeva benissimo dove finivano le sue statue?', [('Restano', 'i:question|LE DOMANDE APERTE'), ('vittima', 'ii:chisel|VITTIMA?|mask|COMPLICE?')]),
 (10, "La sua versione è che non lo sapeva. Ma c'è un elemento che fa riflettere: le sue opere venivano invecchiate, spezzate, consumate ad arte. Chi fa una scultura in stile per un collezionista dichiarato, di solito non ha bisogno di farla sembrare vecchia di secoli.", [('versione', 'stamp:«NON SAPEVO»'), ('invecchiate', 'i:broken|INVECCHIATE AD ARTE'), ('secoli', 'i:hourglass|PERCHÉ INVECCHIARLE?')]),
 (10, 'E Volpi? Sapeva che le opere vendute come Mino da Fiesole e Simone Martini venivano da una bottega romana del Novecento? Le fonti lette non lo stabiliscono, e nessuna parla di una sua condanna. Quello che risulta è che lo scandalo lo travolse.', [('Volpi', 'fig:suit|ELIA VOLPI'), ('Sapeva', 'i:question|SAPEVA?'), ('condanna', 'stamp:NESSUNA CONDANNA NOTA')]),
 (10, 'Seconda domanda: quanto guadagnarono davvero i mercanti? Nessuna cifra complessiva è confermata da più fonti. Tutte però dicono la stessa cosa: a Dossena andava una parte minima, ai mercanti quasi tutto.', [('Seconda', 'i:moneybag|QUANTO?'), ('cifra', 'stamp:CIFRA NON CONFERMATA'), ('minima', 'ii:payenv|A DOSSENA: POCO|moneybag|AI MERCANTI: QUASI TUTTO')]),
 (10, 'Terza domanda: quante opere di Dossena sono ancora in giro, con un altro nome? Lui stesso aveva prodotto per anni, e molte opere erano state vendute a privati. È possibile che alcune siano ancora considerate antiche, in qualche collezione.', [('Terza', 'i:question|QUANTE SONO?'), ('privati', 'iii:villa|COLLEZIONI PRIVATE|museum|MUSEI|crate|MAGAZZINI'), ('antiche', 'stamp:ANCORA NASCOSTE?')]),
 (10, 'Ci sono infatti studiosi che ancora oggi discutono di singole sculture, attribuite da alcuni a maestri antichi e da altri a Dossena. Il confine tra imitazione e falso, nel suo caso, è diventato esso stesso un tema di studio.', [('studiosi', 'i:meeting|IL DIBATTITO'), ('sculture', 'ii:madonna|MAESTRO ANTICO?|signature|DOSSENA?'), ('confine', 'h:Imitazione\no *falso*?')]),
 (10, "Quarta domanda, la più filosofica: un'opera bella smette di essere bella quando scopriamo chi l'ha fatta? Secondo una ricostruzione, il museo di Boston negli anni successivi rimise in mostra la tomba per un periodo proprio con questa motivazione: perché era un oggetto bello.", [('Quarta', 'i:eye|LA BELLEZZA'), ('bella', 'ii:sarcoph|PRIMA: «MINO»|sarcoph|DOPO: «DOSSENA»'), ('bello', 'stamp:UN OGGETTO BELLO')]),
 (10, 'Su questo punto le fonti sono più sfumate, e la scheda attuale del museo non riporta lo stato di esposizione in modo univoco. Quello che è certo è che la tomba, oggi, porta anche il nome del suo vero autore.', [('fonti', 'stamp:DETTAGLI NON CONCORDI'), ('scheda', 'card:SCHEDA ATTUALE|autori: Dossena · Mino|data: intorno al 1920'), ('autore', 'i:signature|IL VERO AUTORE')]),
 (11, 'E arriviamo alla lezione. Il caso Dossena è di cento anni fa, ma il meccanismo è attualissimo. Vale per una statua, un quadro, un orologio, un oggetto da collezione comprato online. Vediamo cinque regole semplici.', [('lezione', 'i:magnifier|LA LEZIONE'), ('Vale', 'iii:statue|UNA STATUA|easel|UN QUADRO|phone|ONLINE'), ('cinque', 'check:1')]),
 (11, "Prima regola: chiedi sempre la provenienza documentata. Chi possedeva l'oggetto prima, dove, con quali passaggi e con quali carte. Nel caso Dossena, la provenienza era un'abbazia distrutta che non era mai esistita.", [('Prima', 'check:1'), ('provenienza', 'doc:PROVENIENZA|1° proprietario: ?|passaggi: ?|documenti: ?'), ("un'abbazia", 'i:abbey_x|UNA PROVENIENZA INVENTATA')]),
 (11, "Seconda regola: diffida delle storie troppo belle. Il ritrovamento miracoloso, l'opera rimasta nascosta per secoli, il nobile decaduto costretto a vendere. Più la storia è romantica, più va controllata.", [('Seconda', 'check:2'), ('miracoloso', 'i:abbey_x|IL RITROVAMENTO MIRACOLOSO'), ('romantica', 'stamp:DA CONTROLLARE')]),
 (11, "Terza regola: non fidarti di un solo esperto, soprattutto se è legato a chi vende. Nel nostro caso, l'antiquario che vendeva era anche quello che garantiva. Serve una perizia indipendente, magari con analisi scientifiche.", [('Terza', 'check:3'), ('esperto', 'ii:suit|CHI VENDE|magnifier|CHI GARANTISCE'), ('indipendente', 'i:xray|PERIZIA INDIPENDENTE')]),
 (11, 'Quarta regola: guarda dentro i dettagli. Una data che non torna, come quel 1430 su una tomba di uno scultore di un anno. Una firma troppo evidente, come le iniziali di un pittore su una statua. I falsi spesso inciampano proprio lì.', [('Quarta', 'check:4'), ('data', 'big:1430|uno scultore di 1 anno'), ('firma', 'i:signature|LA FIRMA TROPPO EVIDENTE')]),
 (11, "E per chi compra o vende all'estero: un'opera d'arte che ha più di settanta anni, per uscire dall'Italia, ha bisogno di regola di un attestato di libera circolazione, rilasciato dagli uffici esportazione del Ministero della Cultura. Anche questa è una carta che racconta la storia di un oggetto.", [("all'estero", 'map:Roma|10|Roma,New York|Roma>New York'), ('settanta', "big:70 anni|la soglia per l'attestato"), ('attestato', 'doc:ATTESTATO DI LIBERA CIRCOLAZIONE|uffici esportazione|Ministero della Cultura')]),
 (11, "Oggi in Italia la contraffazione di opere d'arte è un reato previsto dal codice penale, rafforzato dalla legge numero 22 del 2022 sui reati contro il patrimonio culturale. Le pene riguardano chi produce un falso e chi lo vende o lo mette in circolazione come autentico.", [('contraffazione', 'i:law|IL CODICE PENALE'), ('22', "doc:LEGGE 9 MARZO 2022 N. 22|reati contro il patrimonio culturale|contraffazione di opere d'arte"), ('autentico', 'ii:workshop|CHI PRODUCE|price|CHI VENDE')]),
 (11, "Quinta regola: in Italia, se hai un dubbio su un'opera d'arte, puoi rivolgerti ai Carabinieri per la tutela del patrimonio culturale, che gestiscono una grande banca dati dei beni rubati. E ricorda che vendere un falso come autentico è un reato, mentre vendere una copia dichiarata come copia è legale.", [('Quinta', 'check:5'), ('Carabinieri', 'i:shield_ok|CARABINIERI TPC'), ('reato', 'ii:mask|FALSO COME AUTENTICO: REATO|signature|COPIA DICHIARATA: LEGALE')]),
 (11, 'Le cinque regole, in breve: provenienza documentata, diffidare delle storie troppo belle, perizia indipendente, attenzione ai dettagli, e nel dubbio chiedere a chi è competente. Sono indicazioni generali, non una consulenza legale.', [('cinque', 'check:5'), ('generali', 't:INDICAZIONI GENERALI · NON CONSULENZA LEGALE')]),
 (12, 'Siamo al verdetto. Primo: Alceo Dossena, scalpellino di Cremona, scolpisce per anni opere nello stile dei grandi maestri, che i suoi mercanti vendono come antiche.', [('verdetto', 'i:gavel|IL VERDETTO'), ('Primo', 'lab:4')]),
 (12, "Secondo: le sue statue entrano nei musei di Boston, Cleveland e New York e nella collezione Frick, per cifre che superano i centomila dollari dell'epoca. Terzo: nel 1928 Dossena confessa di esserne l'autore, e scoppia lo scandalo.", [('Secondo', 'mus:4'), ('Terzo', 'cal:LO SCANDALO|1928')]),
 (12, 'Quarto: al processo viene assolto per insufficienza di prove, e dei mercanti non risulta nessuna condanna. Quinto: nel 1933 trentanove sue opere, vendute come sue, incassano circa novemila dollari in tutto. Sesto: muore povero, a Roma, nel 1937.', [('Quarto', 'court:ASSOLTO'), ('Quinto', 'big:≈ 9.000 $|39 opere · 1933'), ('Sesto', 'cal:ROMA|1937')]),
 (12, "E ora la domanda per te: Dossena era un falsario o un artista ingannato dai suoi mercanti? E un'opera bella vale meno quando scopri chi l'ha fatta? Scrivilo nei commenti.", [('domanda', 'ii:mask|FALSARIO?|chisel|ARTISTA?'), ('commenti', 'i:letter|SCRIVILO NEI COMMENTI')]),
 (12, 'Iscriviti a Fascicolo Italia: ogni giorno un nuovo caso.', [('Iscriviti', 'subscribe')]),
]
